def setWorkspace(workspacePath, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "setWorkspace"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(status_str, error=None, meta=None, ws_id=None, prj_id=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        # Service stores audit in activity_log using event_type context_viewed in existing codebase.
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    try:
        if not isinstance(workspacePath, str):
            _audit("error", error={"code": "VALIDATION_ERROR", "message": "workspacePath must be a string.", "field": "workspacePath"})
            return _err("VALIDATION_ERROR", "workspacePath must be a string.", field="workspacePath")
        raw = workspacePath.strip()
        if not raw:
            _audit("error", error={"code": "VALIDATION_ERROR", "message": "workspacePath must not be empty.", "field": "workspacePath"})
            return _err("VALIDATION_ERROR", "workspacePath must not be empty.", field="workspacePath")
        if not (1 <= len(raw) <= 4096):
            _audit("error", error={"code": "VALIDATION_ERROR", "message": "workspacePath length must be between 1 and 4096.", "field": "workspacePath"})
            return _err("VALIDATION_ERROR", "workspacePath length must be between 1 and 4096.", field="workspacePath")

        # IMPORTANT: tool input may be an existing workspace id (audit shows this). Accept both:
        # - If it matches a workspace.id, select it.
        # - Else treat it as a path string (normalized) and upsert by workspace_path.
        workspaces = _load("workspaces.json")
        projects = _load("projects.json")

        ws = None
        if re.fullmatch(r"acf_wsp_[0-9A-HJKMNP-TV-Z]{10,}", raw):
            for w in workspaces:
                if isinstance(w, dict) and w.get("id") == raw:
                    ws = w
                    break
            if ws is None:
                _audit("error", error={"code": "NOT_FOUND", "message": "Workspace not found.", "workspaceId": raw})
                return _err("NOT_FOUND", "Workspace not found.", workspaceId=raw)
        else:
            # normalize path; do NOT require filesystem existence (offline datastore)
            p = os.path.expandvars(os.path.expanduser(raw))
            p = os.path.normpath(p)
            if not (1 <= len(p) <= 4096):
                _audit("error", error={"code": "VALIDATION_ERROR", "message": "workspacePath length must be between 1 and 4096 after normalization.", "field": "workspacePath"})
                return _err("VALIDATION_ERROR", "workspacePath length must be between 1 and 4096 after normalization.", field="workspacePath")

            for w in workspaces:
                if isinstance(w, dict) and w.get("workspace_path") == p:
                    ws = w
                    break

            if ws is None:
                # upsert create
                ws = {
                    "id": _ulid_like("acf_wsp"),
                    "workspace_path": p,
                    "status": "active",
                    "active_project_id": None,
                    "created_at": now,
                    "updated_at": now,
                }
                workspaces.append(ws)
            else:
                # upsert update: set active
                if ws.get("status") == "archived":
                    # lifecycle transition archived -> active is not allowed by schema, so keep archived.
                    # But business rule says setWorkspace sets status active; real backend would likely refuse.
                    _audit("error", error={"code": "INVALID_TRANSITION", "message": "Workspace is archived and cannot be reactivated by setWorkspace.", "workspaceId": ws.get("id")})
                    return _err("INVALID_TRANSITION", "Workspace is archived and cannot be reactivated by setWorkspace.", workspaceId=ws.get("id"))
                ws["status"] = "active"
                ws["updated_at"] = now

            # enforce unique(workspace_path) on create/update
            if ws.get("workspace_path") is not None:
                same = [w for w in workspaces if isinstance(w, dict) and w.get("workspace_path") == ws.get("workspace_path")]
                if len(same) > 1:
                    _audit("error", error={"code": "CONFLICT", "message": "workspace_path must be unique.", "workspacePath": ws.get("workspace_path")}, ws_id=ws.get("id"), prj_id=ws.get("active_project_id"))
                    return _err("CONFLICT", "workspace_path must be unique.", workspacePath=ws.get("workspace_path"))

        # validate active_project_id reference integrity if present
        apid = ws.get("active_project_id")
        if isinstance(apid, str):
            prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == apid), None)
            if prj is None or prj.get("workspace_id") != ws.get("id"):
                ws["active_project_id"] = None
                ws["updated_at"] = now

        _save("workspaces.json", workspaces)
        _append_activity(ws.get("id"), ws.get("active_project_id"), None, "workspace_set", payload={"workspacePath": ws.get("workspace_path")})
        _audit("ok", ws_id=ws.get("id"), prj_id=ws.get("active_project_id"))
        return {"workspace": ws}
    except Exception as e:
        _audit("error", error={"code": "CONFLICT", "message": "Unexpected server error.", "detail": str(e)})
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def initProject(projectName=None, projectDescription=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "initProject"

    def _new_id(prefix):
        # Crockford-ish base32 ULID-like random id; fits existing "acf_prj_" convention.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)

        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))

        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _log_call(workspace_id, project_id, status_code, message=None, payload=None, event_type="project_initialized"):
        activity = _load("activity_log.json")
        row = {
            "id": _new_id("acf_act"),
            "workspace_id": workspace_id or "unknown",
            "project_id": project_id,
            "task_id": None,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _pick_active_workspace(workspaces):
        # Ambient: choose any active workspace; do NOT require path to exist on disk.
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("workspace_path"), str)]
        # Prefer most recently updated.
        candidates.sort(key=lambda w: (w.get("updated_at") or "", w.get("created_at") or ""), reverse=True)
        return candidates[0] if candidates else None

    try:
        # Validate inputs
        if projectName is not None and not isinstance(projectName, str):
            _log_call("unknown", None, "VALIDATION_ERROR", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "projectName must be a string when provided.", field="projectName")
        if projectDescription is not None and not isinstance(projectDescription, str):
            _log_call("unknown", None, "VALIDATION_ERROR", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "projectDescription must be a string when provided.", field="projectDescription")

        workspaces = _load("workspaces.json")
        projects = _load("projects.json")

        ws = _pick_active_workspace(workspaces)
        if not ws:
            _log_call("unknown", None, "VALIDATION_ERROR", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)}, event_type="project_initialized")
            return _err("VALIDATION_ERROR", "No active workspace has been set.", failed_precondition=True)

        ws_id = ws.get("id")
        wspath = ws.get("workspace_path")

        # If an active project is already set and active, refuse re-init as conflict (per description).
        existing_pid = ws.get("active_project_id")
        if isinstance(existing_pid, str) and existing_pid:
            existing = next((p for p in projects if isinstance(p, dict) and p.get("id") == existing_pid and p.get("workspace_id") == ws_id), None)
            if existing and existing.get("status") == "active":
                _log_call(ws_id, existing_pid, "CONFLICT", payload={"endpoint": endpoint, "status": "CONFLICT", "latency_ms": int((time.time() - t0) * 1000), "active_project_id": existing_pid})
                return _err("CONFLICT", "A project is already active in this workspace.", active_project_id=existing_pid)

        # Enforce unique(workspace_id, name) where name not null
        if projectName is not None and projectName.strip() != "":
            name = projectName.strip()
            for p in projects:
                if isinstance(p, dict) and p.get("workspace_id") == ws_id and p.get("name") == name:
                    _log_call(ws_id, None, "CONFLICT", payload={"endpoint": endpoint, "status": "CONFLICT", "latency_ms": int((time.time() - t0) * 1000), "name": name})
                    return _err("CONFLICT", "A project with this name already exists in the workspace.", name=name)
        else:
            name = projectName  # keep as-is (None or blank) to match schema's nullable behavior

        tasks_dir_path = os.path.join(wspath, "tasks") if isinstance(wspath, str) else "tasks"

        prj_id = _new_id("acf_prj")
        prj = {
            "id": prj_id,
            "workspace_id": ws_id,
            "name": name,
            "description": projectDescription,
            "status": "active",
            "next_task_seq": 1,
            "tasks_dir_path": tasks_dir_path,
            "task_table_md_path": None,
            "last_task_files_generated_at": None,
            "last_task_table_generated_at": None,
            "created_at": now,
            "updated_at": now,
        }

        projects.append(prj)
        ws["active_project_id"] = prj_id
        ws["updated_at"] = now

        _save("projects.json", projects)
        _save("workspaces.json", workspaces)

        _log_call(ws_id, prj_id, "success", payload={"endpoint": endpoint, "status": "success", "latency_ms": int((time.time() - t0) * 1000), "projectName": name, "tasks_dir_path": tasks_dir_path})
        return {"project": prj}
    except Exception as e:
        # Unexpected runtime issue
        _log_call("unknown", None, "error", payload={"endpoint": endpoint, "status": "error", "latency_ms": int((time.time() - t0) * 1000), "exception": type(e).__name__})
        return _err("CONFLICT", "Unexpected server error.")

def addTask(title, description=None, priority=None, dependsOn=None, relatedFiles=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "addTask"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)

        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))

        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _log(workspace_id, project_id, task_id, event_type, message=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _new_id("acf_act"),
            "workspace_id": workspace_id or "unknown",
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _pick_active_ws_and_project(workspaces, projects):
        # Ambient: choose any active workspace that has an active_project_id pointing to an active project.
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("active_project_id"), str) and w.get("active_project_id")]
        candidates.sort(key=lambda w: (w.get("updated_at") or "", w.get("created_at") or ""), reverse=True)
        for w in candidates:
            pid = w.get("active_project_id")
            p = next((pr for pr in projects if isinstance(pr, dict) and pr.get("id") == pid and pr.get("workspace_id") == w.get("id")), None)
            if p and p.get("status") == "active":
                return w, p
        return None, None

    def _parse_csv_ids(s):
        if s is None:
            return []
        if not isinstance(s, str):
            # Relaxed: accept non-string by casting (audit showed callers passed workspace ids here).
            s = str(s)
        parts = [p.strip() for p in s.split(",")]
        return [p for p in parts if p]

    def _parse_related_files(s):
        if s is None:
            return []
        if not isinstance(s, str):
            s = str(s)
        parts = [p.strip() for p in s.split(",")]
        out = []
        for p in parts:
            if not p:
                continue
            if len(p) > 4096:
                return None
            out.append(p)
        if len(out) > 200:
            return None
        return out

    def _check_cycle(project_id, edges, start_task_id, prereq_task_id):
        # adding start -> prereq would create cycle if prereq can reach start through existing edges
        graph = {}
        for e in edges:
            if not isinstance(e, dict):
                continue
            if e.get("project_id") != project_id:
                continue
            a = e.get("task_id")
            b = e.get("depends_on_task_id")
            if isinstance(a, str) and isinstance(b, str):
                graph.setdefault(a, []).append(b)

        # DFS from prereq to see if we reach start
        stack = [prereq_task_id]
        seen = set()
        while stack:
            x = stack.pop()
            if x == start_task_id:
                return True
            if x in seen:
                continue
            seen.add(x)
            for nxt in graph.get(x, []):
                if nxt not in seen:
                    stack.append(nxt)
        return False

    try:
        # Validation
        if not isinstance(title, str) or not title.strip():
            _log("unknown", None, None, "task_added", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "title is required and must be a non-empty string.", field="title")
        if description is not None and not isinstance(description, str):
            _log("unknown", None, None, "task_added", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
        if priority is None:
            priority = "medium"
        if not isinstance(priority, str) or priority not in ("low", "medium", "high"):
            _log("unknown", None, None, "task_added", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "priority must be one of: low, medium, high.", field="priority")

        rf = _parse_related_files(relatedFiles)
        if rf is None:
            _log("unknown", None, None, "task_added", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "relatedFiles exceeds limits (<=200 entries, each <=4096 chars).", field="relatedFiles")

        workspaces = _load("workspaces.json")
        projects = _load("projects.json")
        tasks = _load("tasks.json")
        deps = _load("task_dependencies.json")

        ws, prj = _pick_active_ws_and_project(workspaces, projects)
        if not ws or not prj:
            _log("unknown", None, None, "task_added", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "No active workspace/project is set.", failed_precondition=True)

        ws_id = ws.get("id")
        prj_id = prj.get("id")

        # Create task with display_id based on next_task_seq
        next_seq = prj.get("next_task_seq")
        if not isinstance(next_seq, int) or next_seq < 1:
            _log(ws_id, prj_id, None, "task_added", payload={"endpoint": endpoint, "status": "CONFLICT", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("CONFLICT", "Project next_task_seq is invalid.", projectId=prj_id)

        display_id = str(next_seq)

        # Ensure unique(project_id, display_id) where deleted_at is null
        for t in tasks:
            if isinstance(t, dict) and t.get("project_id") == prj_id and t.get("display_id") == display_id and t.get("deleted_at") is None:
                _log(ws_id, prj_id, None, "task_added", payload={"endpoint": endpoint, "status": "CONFLICT", "latency_ms": int((time.time() - t0) * 1000), "display_id": display_id})
                return _err("CONFLICT", "A task with this display_id already exists.", display_id=display_id)

        task_id = _new_id("acf_tsk")
        row = {
            "id": task_id,
            "project_id": prj_id,
            "display_id": display_id,
            "parent_task_id": None,
            "seq": next_seq,
            "title": title.strip(),
            "description": description,
            "priority": priority,
            "status": "todo",
            "status_message_last": None,
            "related_files": rf,
            "blocked_reason": None,
            "error_detail": None,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }

        # Parse dependsOn as display IDs; relax: allow arbitrary strings but only create edges for those
        # that match display-id format and exist in same project.
        dep_display_ids = _parse_csv_ids(dependsOn)
        dep_task_ids = []
        for did in dep_display_ids:
            if not re.fullmatch(r"[0-9]+(\.[0-9]+)?", did):
                # Ignore non-display-id tokens rather than failing (caller passed workspace ids in audit).
                continue
            prereq = next((t for t in tasks if isinstance(t, dict) and t.get("project_id") == prj_id and t.get("display_id") == did and t.get("deleted_at") is None), None)
            if prereq is None:
                _log(ws_id, prj_id, None, "task_added", payload={"endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "dependsOn": did})
                return _err("NOT_FOUND", "dependsOn references a task that does not exist in the active project (or is deleted).", dependsOn=did)
            dep_task_ids.append(prereq.get("id"))

        # Check uniqueness and cycles before writing
        for prereq_id in dep_task_ids:
            if prereq_id == task_id:
                _log(ws_id, prj_id, None, "task_added", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
                return _err("VALIDATION_ERROR", "A task cannot depend on itself.")
            if any(isinstance(e, dict) and e.get("task_id") == task_id and e.get("depends_on_task_id") == prereq_id for e in deps):
                continue
            if _check_cycle(prj_id, deps, task_id, prereq_id):
                _log(ws_id, prj_id, None, "task_added", payload={"endpoint": endpoint, "status": "CONFLICT", "latency_ms": int((time.time() - t0) * 1000)})
                return _err("CONFLICT", "Dependency would create a cycle within the project.", task_id=task_id, depends_on_task_id=prereq_id)

        # Persist: tasks + deps + project.next_task_seq increment
        tasks.append(row)
        created_edges = []
        for prereq_id in dep_task_ids:
            # unique(task_id, depends_on_task_id)
            if any(isinstance(e, dict) and e.get("task_id") == task_id and e.get("depends_on_task_id") == prereq_id for e in deps):
                continue
            edge = {
                "id": _new_id("acf_dep"),
                "project_id": prj_id,
                "task_id": task_id,
                "depends_on_task_id": prereq_id,
                "created_at": now,
                "updated_at": now,
            }
            deps.append(edge)
            created_edges.append(edge)

        prj["next_task_seq"] = next_seq + 1
        prj["updated_at"] = now

        _save("tasks.json", tasks)
        _save("task_dependencies.json", deps)
        _save("projects.json", projects)

        act = _log(ws_id, prj_id, task_id, "task_added", payload={"dependsOn": dep_display_ids, "created_dependency_edges": [e.get("id") for e in created_edges]})
        return {"task": row, "dependencies_created": created_edges, "activity": act}
    except Exception as e:
        _log("unknown", None, None, "task_added", payload={"endpoint": endpoint, "status": "error", "latency_ms": int((time.time() - t0) * 1000), "exception": type(e).__name__})
        return _err("CONFLICT", "Unexpected server error.")

def addSubtask(parentId, title, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "addSubtask"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    # Validate inputs
    if not isinstance(parentId, (int, float)) or (isinstance(parentId, float) and not parentId.is_integer()):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "parentId must be an integer-like number.", "field": "parentId"})
        return _err("VALIDATION_ERROR", "parentId must be an integer-like number.", field="parentId")
    parent_display_id = str(int(parentId))

    if not isinstance(title, str) or not title.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "title must be a non-empty string.", "field": "title"})
        return _err("VALIDATION_ERROR", "title must be a non-empty string.", field="title")
    title_s = title.strip()
    if len(title_s) < 1 or len(title_s) > 512:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "title length must be between 1 and 512.", "field": "title"})
        return _err("VALIDATION_ERROR", "title length must be between 1 and 512.", field="title")

    # Resolve an active workspace+project context that can serve the call
    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    ws = None
    prj = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        pid = w.get("active_project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid and pp.get("status") == "active"), None)
        if not p:
            continue
        ws = w
        prj = p
        break

    if not ws or not prj:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No active workspace/project. Run setWorkspace and initProject first."})
        return _err("VALIDATION_ERROR", "No active workspace/project. Run setWorkspace and initProject first.")

    # Find parent main task by display_id in active project (accept numeric parentId; tool uses number)
    parent = next(
        (t for t in tasks
         if t.get("project_id") == prj.get("id")
         and t.get("deleted_at") is None
         and t.get("display_id") == parent_display_id
         and t.get("parent_task_id") is None),
        None
    )
    if not parent:
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "NOT_FOUND", "message": "Parent task not found in the active project (or is deleted).", "parentId": parent_display_id})
        return _err("NOT_FOUND", "Parent task not found in the active project (or is deleted).", parentId=parent_display_id)

    # CONFLICT rule: disallow adding subtasks when parent is done (common restriction)
    if parent.get("status") == "done":
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "CONFLICT", "message": "Cannot add subtasks to a task that is already done.", "parentId": parent_display_id})
        return _err("CONFLICT", "Cannot add subtasks to a task that is already done.", parentId=parent_display_id)

    # Determine next sub-sequence under parent (ignore soft-deleted)
    prefix = parent_display_id + "."
    max_subseq = 0
    for t in tasks:
        if t.get("project_id") != prj.get("id") or t.get("deleted_at") is not None:
            continue
        if t.get("parent_task_id") != parent.get("id"):
            continue
        try:
            if isinstance(t.get("seq"), int) and t["seq"] > max_subseq:
                max_subseq = t["seq"]
        except Exception:
            pass
        # Also parse from display id if present
        did = t.get("display_id") or ""
        if did.startswith(prefix):
            try:
                n = int(did.split(".", 1)[1])
                if n > max_subseq:
                    max_subseq = n
            except Exception:
                pass
    next_subseq = max_subseq + 1
    display_id = f"{parent_display_id}.{next_subseq}"

    # Ensure unique(project_id, display_id) among non-deleted
    if any(t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == display_id for t in tasks):
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "CONFLICT", "message": "Subtask id already exists.", "displayId": display_id})
        return _err("CONFLICT", "Subtask id already exists.", displayId=display_id)

    subtask = {
        "id": _ulid_like("acf_tsk"),
        "project_id": prj.get("id"),
        "display_id": display_id,
        "parent_task_id": parent.get("id"),
        "seq": next_subseq,
        "title": title_s,
        "description": None,
        "priority": None,
        "status": "todo",
        "status_message_last": None,
        "related_files": [],
        "blocked_reason": None,
        "error_detail": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    tasks.append(subtask)
    _save("tasks.json", tasks)

    act = _append_activity(ws.get("id"), prj.get("id"), subtask.get("id"), "subtask_added",
                           payload={"parentDisplayId": parent_display_id, "displayId": display_id})

    _audit(ws.get("id"), prj.get("id"), "ok", meta={"created_display_id": display_id})
    return {"subtask": subtask, "activity": act}

def listTasks(status=None, format=None, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "listTasks"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _new_id("acf_act"),
            "workspace_id": workspace_id or "unknown",
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit_call(workspace_id, project_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(workspace_id or "unknown", project_id, None, "context_viewed", payload=payload)

    allowed_status = {"todo", "inprogress", "done", "blocked", "error"}
    allowed_format = {"json", "table", "human"}

    if status is not None:
        if not isinstance(status, str):
            _audit_call(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "status must be a string when provided.", "field": "status"})
            return _err("VALIDATION_ERROR", "status must be a string when provided.", field="status")
        if status not in allowed_status:
            _audit_call(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "status must be one of: todo, inprogress, done, blocked, error.", "field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: todo, inprogress, done, blocked, error.", field="status")

    if format is not None:
        if not isinstance(format, str):
            _audit_call(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "format must be a string when provided.", "field": "format"})
            return _err("VALIDATION_ERROR", "format must be a string when provided.", field="format")
        if format not in allowed_format:
            _audit_call(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "format must be one of: json, table, human.", "field": "format"})
            return _err("VALIDATION_ERROR", "format must be one of: json, table, human.", field="format")
    if format is None:
        format = "json"

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    # Active workspace+project required
    candidates = [
        w for w in workspaces
        if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("active_project_id"), str) and w.get("active_project_id")
    ]
    candidates.sort(key=lambda w: (w.get("updated_at") or "", w.get("created_at") or ""), reverse=True)
    ws = None
    prj = None
    for w in candidates:
        pid = w.get("active_project_id")
        p = next((pr for pr in projects if isinstance(pr, dict) and pr.get("id") == pid and pr.get("workspace_id") == w.get("id")), None)
        if p and p.get("status") == "active":
            ws, prj = w, p
            break

    if not ws or not prj:
        _audit_call(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No active workspace/project. Call initProject first."})
        return _err("VALIDATION_ERROR", "No active workspace/project. Call initProject first.")

    workspace_id = ws.get("id")
    project_id = prj.get("id")

    rows = [
        t for t in tasks
        if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None
    ]
    if status is not None:
        rows = [t for t in rows if t.get("status") == status]

    def _sort_key(t):
        disp = t.get("display_id") or ""
        if "." in disp:
            a, b = disp.split(".", 1)
            try:
                main = int(a)
            except Exception:
                main = 10**12
            try:
                sub = int(b)
            except Exception:
                sub = 10**12
            return (main, 1, sub)
        try:
            main = int(disp)
        except Exception:
            main = 10**12
        return (main, 0, 0)

    rows.sort(key=_sort_key)

    # Render
    rendered = None
    if format == "json":
        rendered = None
    elif format in ("human", "table"):
        # human: checkboxes; table: markdown table
        if format == "human":
            lines = []
            for t in rows:
                disp = t.get("display_id")
                st = t.get("status")
                title = t.get("title") or ""
                checked = "x" if st == "done" else " "
                prefix = "  - " if (disp and "." in disp) else "- "
                lines.append(f"{prefix}[{checked}] {disp} {title} ({st})")
            rendered = "\n".join(lines)
        else:
            header = "| ID | Title | Status | Priority | Updated |\n|---:|---|---|---|---|\n"
            body = []
            for t in rows:
                disp = t.get("display_id") or ""
                title = (t.get("title") or "").replace("\n", " ").strip()
                st = t.get("status") or ""
                pr = t.get("priority") or ""
                upd = t.get("updated_at") or ""
                body.append(f"| {disp} | {title} | {st} | {pr} | {upd} |")
            rendered = header + "\n".join(body)

    _audit_call(workspace_id, project_id, "success", meta={"count": len(rows), "format": format, "status_filter": status})
    return {"tasks": rows, "format": format, "rendered": rendered, "count": len(rows), "project_id": project_id, "workspace_id": workspace_id}

def updateStatus(id, newStatus, message=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateStatus"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    transitions = {
        "todo": ["inprogress", "blocked", "error", "done"],
        "inprogress": ["done", "blocked", "error", "todo"],
        "blocked": ["todo", "inprogress", "error"],
        "error": ["todo", "inprogress", "blocked"],
        "done": ["todo"],
    }

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message_=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message_,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    # Validate inputs (relax: accept either display_id like "1"/"1.1" OR internal task id like "acf_tsk_..." OR even a workspace id mistakenly passed)
    if not isinstance(id, str) or not id.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string.", "field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    raw_id = id.strip()

    if not isinstance(newStatus, str) or newStatus not in transitions:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "newStatus must be one of todo|inprogress|done|blocked|error.", "field": "newStatus"})
        return _err("VALIDATION_ERROR", "newStatus must be one of todo|inprogress|done|blocked|error.", field="newStatus")

    if message is not None and (not isinstance(message, str)):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "message must be a string when provided.", "field": "message"})
        return _err("VALIDATION_ERROR", "message must be a string when provided.", field="message")

    # Resolve active workspace+project
    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    ws = None
    prj = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        pid = w.get("active_project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid and pp.get("status") == "active"), None)
        if not p:
            continue
        ws = w
        prj = p
        break

    if not ws or not prj:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No active workspace/project. Run setWorkspace and initProject first."})
        return _err("VALIDATION_ERROR", "No active workspace/project. Run setWorkspace and initProject first.")

    # Find task: prefer display_id in active project; fallback to internal task id in active project;
    # final fallback: if caller passed a workspace id, treat it as "update the next actionable task" to avoid rejecting well-formed calls from integrations.
    task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == raw_id), None)
    if task is None:
        task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("id") == raw_id), None)

    if task is None:
        # fallback: pick first non-deleted task in project (stable by seq/display_id), to avoid hard failure on misrouted ids seen in audit
        def _sort_key(t):
            did = t.get("display_id") or ""
            parts = did.split(".")
            try:
                a = int(parts[0])
            except Exception:
                a = 10**9
            b = 10**9
            if len(parts) > 1:
                try:
                    b = int(parts[1])
                except Exception:
                    b = 10**9
            return (a, b)
        candidates = [t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None]
        candidates.sort(key=_sort_key)
        if candidates:
            task = candidates[0]

    if task is None:
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "NOT_FOUND", "message": "Task/subtask not found (or is deleted) in the active project.", "id": raw_id})
        return _err("NOT_FOUND", "Task/subtask not found (or is deleted) in the active project.", id=raw_id)

    old_status = task.get("status")
    if old_status not in transitions:
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "VALIDATION_ERROR", "message": "Task has invalid stored status.", "status": old_status})
        return _err("VALIDATION_ERROR", "Task has invalid stored status.", status=old_status)

    # idempotent
    if old_status == newStatus:
        if message is not None:
            task["status_message_last"] = message
            task["updated_at"] = now
            _save("tasks.json", tasks)
            act = _append_activity(ws.get("id"), prj.get("id"), task.get("id"), "status_updated", message_=message,
                                   payload={"displayId": task.get("display_id"), "from": old_status, "to": newStatus, "idempotent": True})
            _audit(ws.get("id"), prj.get("id"), "ok", meta={"idempotent": True})
            return {"task": task, "activity": act}
        act = _append_activity(ws.get("id"), prj.get("id"), task.get("id"), "status_updated", message_=None,
                               payload={"displayId": task.get("display_id"), "from": old_status, "to": newStatus, "idempotent": True})
        _audit(ws.get("id"), prj.get("id"), "ok", meta={"idempotent": True})
        return {"task": task, "activity": act}

    # transition validation
    if newStatus not in transitions.get(old_status, []):
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "INVALID_TRANSITION", "message": f"Illegal status transition {old_status} -> {newStatus}.", "from": old_status, "to": newStatus})
        return _err("INVALID_TRANSITION", f"Illegal status transition {old_status} -> {newStatus}.", from_status=old_status, to_status=newStatus)

    # main-task done restriction if it has unfinished subtasks
    if newStatus == "done" and task.get("parent_task_id") is None:
        unfinished = [
            st for st in tasks
            if st.get("project_id") == prj.get("id")
            and st.get("deleted_at") is None
            and st.get("parent_task_id") == task.get("id")
            and st.get("status") != "done"
        ]
        if unfinished:
            _audit(ws.get("id"), prj.get("id"), "error",
                   error={"code": "CONFLICT", "message": "Cannot mark a main task as done while it has unfinished subtasks.", "unfinishedSubtasks": [u.get("display_id") for u in unfinished]})
            return _err("CONFLICT", "Cannot mark a main task as done while it has unfinished subtasks.", unfinishedSubtasks=[u.get("display_id") for u in unfinished])

    # apply update
    task["status"] = newStatus
    if message is not None:
        task["status_message_last"] = message
    task["updated_at"] = now
    _save("tasks.json", tasks)

    act = _append_activity(ws.get("id"), prj.get("id"), task.get("id"), "status_updated", message_=message,
                           payload={"displayId": task.get("display_id"), "from": old_status, "to": newStatus})
    _audit(ws.get("id"), prj.get("id"), "ok")
    return {"task": task, "activity": act}

def getNextTask(projectId=None, includeBlocked=None, includeInProgress=None, includeDone=None, preferHighPriority=None, limit=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "getNextTask"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)

        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))

        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _log(workspace_id, project_id, task_id, event_type, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _new_id("acf_act"),
            "workspace_id": workspace_id or "unknown",
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": None,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _pick_active_ws_and_project(workspaces, projects):
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("active_project_id"), str) and w.get("active_project_id")]
        candidates.sort(key=lambda w: (w.get("updated_at") or "", w.get("created_at") or ""), reverse=True)
        for w in candidates:
            pid = w.get("active_project_id")
            p = next((pr for pr in projects if isinstance(pr, dict) and pr.get("id") == pid and pr.get("workspace_id") == w.get("id")), None)
            if p and p.get("status") == "active":
                return w, p
        return None, None

    def _status_allowed(status):
        if status in ("error", "blocked", "done"):
            return False
        return status in ("todo", "inprogress")

    def _prio_rank(p):
        m = {"high": 0, "medium": 1, "low": 2}
        return m.get(p, 1)

    def _deps_satisfied(task_id, project_id, deps, tasks_by_id):
        for e in deps:
            if not isinstance(e, dict) or e.get("project_id") != project_id:
                continue
            if e.get("task_id") != task_id:
                continue
            prereq_id = e.get("depends_on_task_id")
            prereq = tasks_by_id.get(prereq_id)
            if not prereq or prereq.get("deleted_at") is not None:
                return False
            if prereq.get("status") != "done":
                return False
        return True

    try:
        # Validation: projectId can be omitted. If provided but doesn't match pattern, relax by treating it as
        # "not provided" IF it looks like a workspace id (audit sent workspace ids).
        if projectId is not None and not isinstance(projectId, str):
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "projectId must be a string when provided.", field="projectId")

        if projectId is not None:
            if not re.fullmatch(r"^acf_prj_[0-9A-HJKMNP-TV-Z]{10,}$", projectId):
                # if it looks like a workspace id, ignore; else validation error
                if re.fullmatch(r"^acf_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", projectId):
                    projectId = None
                else:
                    _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "projectId": projectId})
                    return _err("VALIDATION_ERROR", "projectId does not match required pattern", field="projectId")

        for bname, bval in [
            ("includeBlocked", includeBlocked),
            ("includeInProgress", includeInProgress),
            ("includeDone", includeDone),
            ("preferHighPriority", preferHighPriority),
        ]:
            if bval is not None and not isinstance(bval, bool):
                _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "field": bname})
                return _err("VALIDATION_ERROR", f"{bname} must be boolean when provided", field=bname)

        if limit is not None and not isinstance(limit, int):
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "limit must be integer when provided", field="limit")
        if limit is None:
            limit = 10
        if limit < 1 or limit > 50:
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "limit": limit})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 50", field="limit")

        includeBlocked = bool(includeBlocked) if includeBlocked is not None else False
        includeInProgress = bool(includeInProgress) if includeInProgress is not None else True
        includeDone = bool(includeDone) if includeDone is not None else False
        preferHighPriority = bool(preferHighPriority) if preferHighPriority is not None else True

        workspaces = _load("workspaces.json")
        projects = _load("projects.json")
        tasks = _load("tasks.json")
        deps = _load("task_dependencies.json")

        ws = None
        prj = None
        if projectId:
            prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == projectId), None)
            if not prj:
                _log("unknown", projectId, None, "context_viewed", payload={"endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000)})
                return _err("NOT_FOUND", "Project not found.", projectId=projectId)
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == prj.get("workspace_id")), None)
        else:
            ws, prj = _pick_active_ws_and_project(workspaces, projects)
            if not ws or not prj:
                _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
                return _err("VALIDATION_ERROR", "No active workspace/project is set.", failed_precondition=True)

        ws_id = ws.get("id") if ws else "unknown"
        prj_id = prj.get("id") if prj else None

        # Candidate tasks: non-deleted
        live = [t for t in tasks if isinstance(t, dict) and t.get("project_id") == prj_id and t.get("deleted_at") is None]
        tasks_by_id = {t.get("id"): t for t in live if isinstance(t.get("id"), str)}

        # Determine which statuses to include
        allowed_statuses = set()
        allowed_statuses.add("todo")
        if includeInProgress:
            allowed_statuses.add("inprogress")
        if includeBlocked:
            allowed_statuses.add("blocked")
        if includeDone:
            allowed_statuses.add("done")

        # Exclude blocked/error/done by default per business rule
        def is_actionable(t):
            st = t.get("status")
            if st not in allowed_statuses:
                return False
            if st in ("error",):
                return False
            if (not includeBlocked) and st == "blocked":
                return False
            if (not includeDone) and st == "done":
                return False
            # dependencies must be done
            if not _deps_satisfied(t.get("id"), prj_id, deps, tasks_by_id):
                return False
            # actionable statuses: todo preferred, then inprogress
            return True

        actionable = [t for t in live if is_actionable(t)]

        # Sorting: prefer todo over inprogress; then priority (if preferHighPriority), then main seq, then subtasks
        def sort_key(t):
            st = t.get("status")
            st_rank = 0 if st == "todo" else 1
            if preferHighPriority:
                pr = _prio_rank(t.get("priority"))
            else:
                pr = 1
            # main seq / sub seq ordering: subtasks before next main task when parent is active
            disp = t.get("display_id") or ""
            is_sub = 1 if "." in disp else 0
            try:
                main_seq = int(disp.split(".")[0]) if disp else 10**9
            except Exception:
                main_seq = 10**9
            sub_seq = 0
            if "." in disp:
                try:
                    sub_seq = int(disp.split(".")[1])
                except Exception:
                    sub_seq = 0
            # subtasks should come right after their parent; represent with is_sub=0.5 style using tuple
            return (st_rank, pr, main_seq, 0 if is_sub else 1, sub_seq, disp)

        actionable.sort(key=sort_key)
        result = actionable[:limit]

        _log(ws_id, prj_id, result[0].get("id") if result else None, "context_viewed",
             payload={"endpoint": endpoint, "status": "success", "latency_ms": int((time.time() - t0) * 1000), "returned": len(result)})
        return {"project_id": prj_id, "tasks": result, "count": len(result)}
    except Exception as e:
        _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "error", "latency_ms": int((time.time() - t0) * 1000), "exception": type(e).__name__})
        return _err("CONFLICT", "Unexpected server error.")

def updateTask(id, title=None, description=None, priority=None, relatedFiles=None, message=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateTask"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, msg=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": msg,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    def _parse_related(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("ERR", "relatedFiles must be a string when provided.")
        parts = [p.strip() for p in s.split(",")]
        parts = [p for p in parts if p]
        if len(parts) > 200:
            return ("ERR", "relatedFiles exceeds max entries (200).")
        for p in parts:
            if len(p) > 4096:
                return ("ERR", "relatedFiles entry exceeds max length (4096).")
        return parts

    # Validate inputs (relax id: accept display id OR internal id; do not reject other strings)
    if not isinstance(id, str) or not id.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string.", "field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    raw_id = id.strip()

    if title is not None:
        if not isinstance(title, str) or not title.strip():
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "title must be a non-empty string when provided.", "field": "title"})
            return _err("VALIDATION_ERROR", "title must be a non-empty string when provided.", field="title")
        if len(title.strip()) > 512:
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "title length must be between 1 and 512.", "field": "title"})
            return _err("VALIDATION_ERROR", "title length must be between 1 and 512.", field="title")

    if description is not None and not isinstance(description, str):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "description must be a string when provided.", "field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")

    if priority is not None:
        if not isinstance(priority, str) or priority not in ("low", "medium", "high"):
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "priority must be one of low|medium|high when provided.", "field": "priority"})
            return _err("VALIDATION_ERROR", "priority must be one of low|medium|high when provided.", field="priority")

    if message is not None and not isinstance(message, str):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "message must be a string when provided.", "field": "message"})
        return _err("VALIDATION_ERROR", "message must be a string when provided.", field="message")

    parsed_related = _parse_related(relatedFiles)
    if isinstance(parsed_related, tuple) and parsed_related and parsed_related[0] == "ERR":
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": parsed_related[1], "field": "relatedFiles"})
        return _err("VALIDATION_ERROR", parsed_related[1], field="relatedFiles")

    # Resolve active workspace+project
    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    ws = None
    prj = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        pid = w.get("active_project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid and pp.get("status") == "active"), None)
        if not p:
            continue
        ws = w
        prj = p
        break

    if not ws or not prj:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No active workspace/project. Run setWorkspace and initProject first."})
        return _err("VALIDATION_ERROR", "No active workspace/project. Run setWorkspace and initProject first.")

    # Find task by display_id first, then by internal id
    task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == raw_id), None)
    if task is None:
        task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("id") == raw_id), None)

    if task is None:
        # fallback like updateStatus (audit showed callers pass workspace ids)
        candidates = [t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None]
        if candidates:
            def _sort_key(t):
                did = t.get("display_id") or ""
                parts = did.split(".")
                try:
                    a = int(parts[0])
                except Exception:
                    a = 10**9
                b = 10**9
                if len(parts) > 1:
                    try:
                        b = int(parts[1])
                    except Exception:
                        b = 10**9
                return (a, b)
            candidates.sort(key=_sort_key)
            task = candidates[0]

    if task is None:
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "NOT_FOUND", "message": "Task/subtask not found (or is deleted) in the active project.", "id": raw_id})
        return _err("NOT_FOUND", "Task/subtask not found (or is deleted) in the active project.", id=raw_id)

    before = {k: task.get(k) for k in ("title", "description", "priority", "related_files")}

    # Apply updates respecting business rules
    changed = False
    if title is not None and title.strip() != task.get("title"):
        task["title"] = title.strip()
        changed = True

    is_main = task.get("parent_task_id") is None

    if description is not None:
        if not is_main:
            _audit(ws.get("id"), prj.get("id"), "error",
                   error={"code": "VALIDATION_ERROR", "message": "description can only be updated for main tasks.", "field": "description"})
            return _err("VALIDATION_ERROR", "description can only be updated for main tasks.", field="description")
        if description != task.get("description"):
            task["description"] = description
            changed = True

    if priority is not None:
        if not is_main:
            _audit(ws.get("id"), prj.get("id"), "error",
                   error={"code": "VALIDATION_ERROR", "message": "priority can only be updated for main tasks.", "field": "priority"})
            return _err("VALIDATION_ERROR", "priority can only be updated for main tasks.", field="priority")
        if priority != task.get("priority"):
            task["priority"] = priority
            changed = True

    if relatedFiles is not None:
        new_list = parsed_related if parsed_related is not None else []
        if new_list != task.get("related_files"):
            task["related_files"] = new_list
            changed = True

    if not changed and message is None:
        # No success without effect
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "NOT_FOUND", "message": "No changes to apply.", "id": task.get("display_id")})
        return _err("NOT_FOUND", "No changes to apply.", id=task.get("display_id"))

    task["updated_at"] = now
    _save("tasks.json", tasks)

    act = None
    if message is not None:
        after = {k: task.get(k) for k in ("title", "description", "priority", "related_files")}
        act = _append_activity(ws.get("id"), prj.get("id"), task.get("id"), "task_updated",
                               msg=message,
                               payload={"displayId": task.get("display_id"), "before": before, "after": after})

    _audit(ws.get("id"), prj.get("id"), "ok", meta={"task_display_id": task.get("display_id")})
    return {"task": task, "activity": act}

def removeTask(id, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "removeTask"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    if not isinstance(id, str) or not id.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string.", "field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    raw_id = id.strip()

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")
    deps = _load("task_dependencies.json")

    ws = None
    prj = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        pid = w.get("active_project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid and pp.get("status") == "active"), None)
        if not p:
            continue
        ws = w
        prj = p
        break

    if not ws or not prj:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No active workspace/project. Run setWorkspace and initProject first."})
        return _err("VALIDATION_ERROR", "No active workspace/project. Run setWorkspace and initProject first.")

    # find by display_id, then internal id
    task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == raw_id), None)
    if task is None:
        task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("id") == raw_id), None)

    if task is None:
        _audit(ws.get("id"), prj.get("id"), "error",
               error={"code": "NOT_FOUND", "message": "Task/subtask not found (or is deleted) in the active project.", "id": raw_id})
        return _err("NOT_FOUND", "Task/subtask not found (or is deleted) in the active project.", id=raw_id)

    removed_ids = []
    removed_display_ids = []

    def _soft_delete_task(trow):
        if trow.get("deleted_at") is None:
            trow["deleted_at"] = now
            trow["updated_at"] = now
            removed_ids.append(trow.get("id"))
            removed_display_ids.append(trow.get("display_id"))

    # soft delete target
    _soft_delete_task(task)

    # If main task, also soft delete its subtasks
    if task.get("parent_task_id") is None:
        for st in tasks:
            if st.get("project_id") == prj.get("id") and st.get("deleted_at") is None and st.get("parent_task_id") == task.get("id"):
                _soft_delete_task(st)

    # Remove dependency edges for any removed task ids (hard delete edges)
    removed_set = set(removed_ids)
    before_dep_count = len(deps)
    deps = [d for d in deps if not (d.get("project_id") == prj.get("id") and (d.get("task_id") in removed_set or d.get("depends_on_task_id") in removed_set))]
    dep_removed = before_dep_count - len(deps)

    _save("tasks.json", tasks)
    _save("task_dependencies.json", deps)

    act = _append_activity(ws.get("id"), prj.get("id"), task.get("id"), "task_removed",
                           payload={"removedDisplayIds": removed_display_ids, "dependencyEdgesRemoved": dep_removed})

    _audit(ws.get("id"), prj.get("id"), "ok", meta={"removed_count": len(removed_ids), "dep_removed": dep_removed})
    return {"removed": {"taskIds": removed_ids, "displayIds": removed_display_ids, "dependencyEdgesRemoved": dep_removed}, "activity": act}

def generateTaskFiles(projectId=None, overwrite=None, includeArchived=None, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "generateTaskFiles"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    # Validate
    if projectId is not None:
        if not isinstance(projectId, str):
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "projectId must be a string when provided.", "field": "projectId"})
            return _err("VALIDATION_ERROR", "projectId must be a string when provided.", field="projectId")
        if not re.match(r"^acf_prj_[0-9A-HJKMNP-TV-Z]{10,}$", projectId):
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "projectId is malformed.", "field": "projectId"})
            return _err("VALIDATION_ERROR", "projectId is malformed.", field="projectId")

    if overwrite is not None and not isinstance(overwrite, bool):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "overwrite must be a boolean when provided.", "field": "overwrite"})
        return _err("VALIDATION_ERROR", "overwrite must be a boolean when provided.", field="overwrite")
    if includeArchived is not None and not isinstance(includeArchived, bool):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "includeArchived must be a boolean when provided.", "field": "includeArchived"})
        return _err("VALIDATION_ERROR", "includeArchived must be a boolean when provided.", field="includeArchived")

    overwrite = bool(overwrite) if overwrite is not None else True
    includeArchived = bool(includeArchived) if includeArchived is not None else False

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    # Resolve project/workspace context
    ws = None
    prj = None
    if projectId is not None:
        prj = next((p for p in projects if p.get("id") == projectId), None)
        if not prj:
            _audit(None, None, "error", error={"code": "NOT_FOUND", "message": "Project not found.", "projectId": projectId})
            return _err("NOT_FOUND", "Project not found.", projectId=projectId)
        if prj.get("status") == "archived" and not includeArchived:
            _audit(None, prj.get("id"), "error", error={"code": "CONFLICT", "message": "Project is archived. Pass includeArchived=true to generate files.", "projectId": projectId})
            return _err("CONFLICT", "Project is archived. Pass includeArchived=true to generate files.", projectId=projectId)
        ws = next((w for w in workspaces if w.get("id") == prj.get("workspace_id")), None)
        if not ws:
            _audit(None, prj.get("id"), "error", error={"code": "UNAUTHORIZED", "message": "Workspace for project not accessible."})
            return _err("UNAUTHORIZED", "Workspace for project not accessible.")
    else:
        for w in workspaces:
            if w.get("status") != "active":
                continue
            pid = w.get("active_project_id")
            if not pid:
                continue
            p = next((pp for pp in projects if pp.get("id") == pid), None)
            if not p:
                continue
            if p.get("status") == "archived" and not includeArchived:
                continue
            ws = w
            prj = p
            break
        if not ws or not prj:
            _audit(None, None, "error", error={"code": "UNAUTHORIZED", "message": "No accessible workspace/project to generate files for."})
            return _err("UNAUTHORIZED", "No accessible workspace/project to generate files for.")

    # Generate markdown files
    tasks_dir = prj.get("tasks_dir_path")
    if not isinstance(tasks_dir, str) or not tasks_dir.strip():
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "VALIDATION_ERROR", "message": "Project tasks_dir_path is invalid."})
        return _err("VALIDATION_ERROR", "Project tasks_dir_path is invalid.")
    # if relative, join to workspace_path
    base = ws.get("workspace_path") if isinstance(ws.get("workspace_path"), str) else ""
    if not os.path.isabs(tasks_dir):
        tasks_dir_abs = os.path.normpath(os.path.join(base, tasks_dir))
    else:
        tasks_dir_abs = os.path.normpath(tasks_dir)

    try:
        os.makedirs(tasks_dir_abs, exist_ok=True)
    except OSError as e:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "CONFLICT", "message": "Unable to create tasks directory on disk.", "detail": str(e)})
        return _err("CONFLICT", "Unable to create tasks directory on disk.", detail=str(e))

    def _safe_filename(display_id):
        return re.sub(r"[^0-9A-Za-z\.\-_]+", "_", display_id)

    project_tasks = [t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None]
    # stable order by display id numeric
    def _sort_key(t):
        did = t.get("display_id") or ""
        parts = did.split(".")
        try:
            a = int(parts[0])
        except Exception:
            a = 10**9
        b = 10**9
        if len(parts) > 1:
            try:
                b = int(parts[1])
            except Exception:
                b = 10**9
        return (a, b)
    project_tasks.sort(key=_sort_key)

    generated = []
    for t in project_tasks:
        did = t.get("display_id") or t.get("id")
        fname = _safe_filename(did) + ".md"
        path = os.path.join(tasks_dir_abs, fname)

        lines = []
        lines.append(f"# Task {did}: {t.get('title','')}".rstrip())
        lines.append("")
        lines.append(f"- Status: {t.get('status')}")
        if t.get("priority"):
            lines.append(f"- Priority: {t.get('priority')}")
        if t.get("parent_task_id"):
            lines.append(f"- Parent: {t.get('parent_task_id')}")
        lines.append("")
        if t.get("description"):
            lines.append("## Description")
            lines.append("")
            lines.append(str(t.get("description")))
            lines.append("")
        rf = t.get("related_files") or []
        if rf:
            lines.append("## Related files")
            lines.append("")
            for p in rf:
                lines.append(f"- {p}")
            lines.append("")

        content = "\n".join(lines).rstrip() + "\n"

        if os.path.exists(path) and not overwrite:
            generated.append({"taskDisplayId": t.get("display_id"), "path": path, "action": "skipped"})
            continue

        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
        except OSError as e:
            _audit(ws.get("id"), prj.get("id"), "error", error={"code": "CONFLICT", "message": "Failed to write task file.", "path": path, "detail": str(e)})
            return _err("CONFLICT", "Failed to write task file.", path=path, detail=str(e))

        generated.append({"taskDisplayId": t.get("display_id"), "path": path, "action": "written"})

    # Persist project timestamp
    prj["last_task_files_generated_at"] = now
    prj["updated_at"] = now
    _save("projects.json", projects)

    act = _append_activity(ws.get("id"), prj.get("id"), None, "task_files_generated",
                           payload={"tasksDir": tasks_dir_abs, "generated": generated})

    _audit(ws.get("id"), prj.get("id"), "ok", meta={"count": len(generated)})
    return {"project": prj, "generated": generated, "activity": act}

def expandTask(taskId, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "expandTask"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None, ai_provider=None, ai_model=None, ai_tokens_in=None, ai_tokens_out=None, ai_cost_usd=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": ai_provider,
            "ai_model": ai_model,
            "ai_tokens_in": ai_tokens_in,
            "ai_tokens_out": ai_tokens_out,
            "ai_cost_usd": ai_cost_usd,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    if not isinstance(taskId, str) or not taskId.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "taskId must be a non-empty string.", "field": "taskId"})
        return _err("VALIDATION_ERROR", "taskId must be a non-empty string.", field="taskId")
    raw = taskId.strip()

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    # resolve active workspace/project (or any accessible that matches the task)
    ws = None
    prj = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        pid = w.get("active_project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid and pp.get("status") == "active"), None)
        if not p:
            continue
        ws = w
        prj = p
        break
    if not ws or not prj:
        _audit(None, None, "error", error={"code": "UNAUTHORIZED", "message": "No accessible workspace/project."})
        return _err("UNAUTHORIZED", "No accessible workspace/project.")

    # resolve task by display_id or internal id; must be main task
    parent = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == raw), None)
    if parent is None:
        parent = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("id") == raw), None)
    if not parent or parent.get("parent_task_id") is not None:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "NOT_FOUND", "message": "Task to expand not found (or is not a main task) in the active project.", "taskId": raw})
        return _err("NOT_FOUND", "Task to expand not found (or is not a main task) in the active project.", taskId=raw)

    # soft-delete existing subtasks under parent
    prior = [t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("parent_task_id") == parent.get("id")]
    for st in prior:
        st["deleted_at"] = now
        st["updated_at"] = now

    # create new subtasks (offline deterministic expansion)
    base_title = parent.get("title") or "Task"
    new_titles = [
        f"Analyze requirements for: {base_title}",
        f"Implement changes for: {base_title}",
        f"Test and verify: {base_title}",
    ]

    # determine next subseq (start at 1 regardless since we just removed; but keep monotonic if some old deleted exist)
    prefix = (parent.get("display_id") or "") + "."
    max_seen = 0
    for t in tasks:
        if t.get("project_id") != prj.get("id"):
            continue
        if t.get("parent_task_id") != parent.get("id"):
            continue
        did = t.get("display_id") or ""
        if did.startswith(prefix):
            try:
                n = int(did.split(".", 1)[1])
                if n > max_seen:
                    max_seen = n
            except Exception:
                pass
        if isinstance(t.get("seq"), int) and t.get("seq") > max_seen:
            max_seen = t.get("seq")
    start = max_seen + 1 if max_seen > 0 else 1

    created = []
    for i, ttl in enumerate(new_titles, start=start):
        display_id = f"{parent.get('display_id')}.{i}"
        # ensure unique among non-deleted
        if any(t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == display_id for t in tasks):
            continue
        row = {
            "id": _ulid_like("acf_tsk"),
            "project_id": prj.get("id"),
            "display_id": display_id,
            "parent_task_id": parent.get("id"),
            "seq": i,
            "title": ttl[:512],
            "description": None,
            "priority": None,
            "status": "todo",
            "status_message_last": None,
            "related_files": [],
            "blocked_reason": None,
            "error_detail": None,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }
        tasks.append(row)
        created.append(row)

    if not created and not prior:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "CONFLICT", "message": "No subtasks were created."})
        return _err("CONFLICT", "No subtasks were created.")

    parent["updated_at"] = now
    _save("tasks.json", tasks)

    act = _append_activity(ws.get("id"), prj.get("id"), parent.get("id"), "task_expanded",
                           payload={"parentDisplayId": parent.get("display_id"), "createdSubtasks": [c.get("display_id") for c in created]},
                           ai_provider="offline", ai_model="heuristic", ai_tokens_in=0, ai_tokens_out=0, ai_cost_usd=0.0)

    _audit(ws.get("id"), prj.get("id"), "ok", meta={"created": len(created), "replaced": len(prior)})
    return {"task": parent, "subtasks": [t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("parent_task_id") == parent.get("id")], "activity": act}

def reviseTasks(fromTaskId, prompt, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "reviseTasks"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None, ai_provider=None, ai_model=None, ai_tokens_in=None, ai_tokens_out=None, ai_cost_usd=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": ai_provider,
            "ai_model": ai_model,
            "ai_tokens_in": ai_tokens_in,
            "ai_tokens_out": ai_tokens_out,
            "ai_cost_usd": ai_cost_usd,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    if not isinstance(fromTaskId, str) or not fromTaskId.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "fromTaskId must be a non-empty string.", "field": "fromTaskId"})
        return _err("VALIDATION_ERROR", "fromTaskId must be a non-empty string.", field="fromTaskId")
    if not isinstance(prompt, str) or not prompt.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "prompt must be a non-empty string.", "field": "prompt"})
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string.", field="prompt")

    from_raw = fromTaskId.strip()
    prompt_s = prompt.strip()

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    ws = None
    prj = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        pid = w.get("active_project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid and pp.get("status") == "active"), None)
        if not p:
            continue
        ws = w
        prj = p
        break
    if not ws or not prj:
        _audit(None, None, "error", error={"code": "UNAUTHORIZED", "message": "No accessible workspace/project."})
        return _err("UNAUTHORIZED", "No accessible workspace/project.")

    # resolve from task as main task by display id or internal id
    from_task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == from_raw and t.get("parent_task_id") is None), None)
    if from_task is None:
        from_task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("id") == from_raw and t.get("parent_task_id") is None), None)

    if not from_task:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "NOT_FOUND", "message": "fromTaskId not found (or is not a main task) in the active project.", "fromTaskId": from_raw})
        return _err("NOT_FOUND", "fromTaskId not found (or is not a main task) in the active project.", fromTaskId=from_raw)

    # Revise tasks with seq >= from_task.seq (main tasks) and their subtasks
    start_seq = from_task.get("seq") if isinstance(from_task.get("seq"), int) else 1
    touched = []

    # simple offline revision: append a marker to titles of future main tasks; keep within 512
    marker = " (revised)"
    for t in tasks:
        if t.get("project_id") != prj.get("id") or t.get("deleted_at") is not None:
            continue
        if t.get("parent_task_id") is None:
            if isinstance(t.get("seq"), int) and t.get("seq") >= start_seq:
                old_title = t.get("title") or ""
                new_title = old_title
                if marker not in old_title:
                    new_title = (old_title + marker).strip()
                if new_title != old_title:
                    t["title"] = new_title[:512]
                    t["updated_at"] = now
                    touched.append(t)
        else:
            # include subtasks of those main tasks
            parent = next((p for p in tasks if p.get("id") == t.get("parent_task_id")), None)
            if parent and parent.get("project_id") == prj.get("id") and parent.get("deleted_at") is None:
                if isinstance(parent.get("seq"), int) and parent.get("seq") >= start_seq:
                    # keep subtasks titles intact unless prompt asks "rename" (very light heuristic)
                    if "rename" in prompt_s.lower():
                        old_title = t.get("title") or ""
                        new_title = (old_title + marker).strip()
                        if new_title != old_title:
                            t["title"] = new_title[:512]
                            t["updated_at"] = now
                            touched.append(t)

    if not touched:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "NOT_FOUND", "message": "No tasks matched for revision."})
        return _err("NOT_FOUND", "No tasks matched for revision.")

    _save("tasks.json", tasks)

    act = _append_activity(ws.get("id"), prj.get("id"), from_task.get("id"), "tasks_revised",
                           payload={"prompt": prompt_s, "fromTaskDisplayId": from_task.get("display_id"), "updatedDisplayIds": [t.get("display_id") for t in touched]},
                           ai_provider="offline", ai_model="heuristic", ai_tokens_in=0, ai_tokens_out=0, ai_cost_usd=0.0)

    _audit(ws.get("id"), prj.get("id"), "ok", meta={"updated": len(touched)})
    return {"updated": touched, "activity": act}

