    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "generateTaskTable"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, event_type, message=None, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": message,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, "context_viewed", payload=payload)

    if projectId is not None:
        if not isinstance(projectId, str):
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "projectId must be a string when provided.", "field": "projectId"})
            return _err("VALIDATION_ERROR", "projectId must be a string when provided.", field="projectId")
        if not re.match(r"^acf_prj_[0-9A-HJKMNP-TV-Z]{10,}$", projectId):
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "projectId is malformed.", "field": "projectId"})
            return _err("VALIDATION_ERROR", "projectId is malformed.", field="projectId")
    if includeSubtasks is not None and not isinstance(includeSubtasks, bool):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "includeSubtasks must be boolean when provided.", "field": "includeSubtasks"})
        return _err("VALIDATION_ERROR", "includeSubtasks must be boolean when provided.", field="includeSubtasks")
    if includeDone is not None and not isinstance(includeDone, bool):
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "includeDone must be boolean when provided.", "field": "includeDone"})
        return _err("VALIDATION_ERROR", "includeDone must be boolean when provided.", field="includeDone")
    if sortBy is not None:
        if not isinstance(sortBy, str) or sortBy not in ("displayId", "priority", "status", "updatedAt"):
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "sortBy must be one of displayId|priority|status|updatedAt when provided.", "field": "sortBy"})
            return _err("VALIDATION_ERROR", "sortBy must be one of displayId|priority|status|updatedAt when provided.", field="sortBy")

    includeSubtasks = includeSubtasks if includeSubtasks is not None else True
    includeDone = includeDone if includeDone is not None else True
    sortBy = sortBy if sortBy is not None else "displayId"

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    # resolve project
    ws = None
    prj = None
    if projectId:
        prj = next((p for p in projects if p.get("id") == projectId), None)
        if not prj:
            _audit(None, None, "error", error={"code": "NOT_FOUND", "message": "Project not found.", "projectId": projectId})
            return _err("NOT_FOUND", "Project not found.", projectId=projectId)
        ws = next((w for w in workspaces if w.get("id") == prj.get("workspace_id")), None)
        if not ws:
            _audit(None, prj.get("id"), "error", error={"code": "UNAUTHORIZED", "message": "Workspace for project not accessible."})
            return _err("UNAUTHORIZED", "Workspace for project not accessible.")
    else:
        for w in workspaces:
            if w.get("status") != "active":
                continue
            pid = w.get("active_project_id")
            if not pid:
                continue
            p = next((pp for pp in projects if pp.get("id") == pid), None)
            if not p:
                continue
            ws = w
            prj = p
            break
        if not ws or not prj:
            _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No active workspace/project. Run setWorkspace and initProject first."})
            return _err("VALIDATION_ERROR", "No active workspace/project. Run setWorkspace and initProject first.")

    rows = [t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None]
    if not includeDone:
        rows = [t for t in rows if t.get("status") != "done"]
    if not includeSubtasks:
        rows = [t for t in rows if t.get("parent_task_id") is None]

    def _display_sort(t):
        did = t.get("display_id") or ""
        parts = did.split(".")
        try:
            a = int(parts[0])
        except Exception:
            a = 10**9
        b = 10**9
        if len(parts) > 1:
            try:
                b = int(parts[1])
            except Exception:
                b = 10**9
        return (a, b)

    prio_rank = {"high": 0, "medium": 1, "low": 2, None: 3}
    status_rank = {"todo": 0, "inprogress": 1, "blocked": 2, "error": 3, "done": 4}

    if sortBy == "displayId":
        rows.sort(key=_display_sort)
    elif sortBy == "priority":
        rows.sort(key=lambda t: (prio_rank.get(t.get("priority"), 3),) + _display_sort(t))
    elif sortBy == "status":
        rows.sort(key=lambda t: (status_rank.get(t.get("status"), 99),) + _display_sort(t))
    elif sortBy == "updatedAt":
        rows.sort(key=lambda t: (t.get("updated_at") or "",) + tuple(_display_sort(t)))

    # Render markdown
    def _checkbox(status):
        return "[x]" if status == "done" else "[ ]"

    lines = []
    lines.append(f"# Task Table: {prj.get('name') or prj.get('id')}")
    lines.append("")
    lines.append("| ID | Title | Status | Priority | |")
    lines.append("|---:|-------|--------|----------|---|")
    for t in rows:
        did = t.get("display_id")
        ttl = (t.get("title") or "").replace("\n", " ").strip()
        st = t.get("status") or ""
        pr = t.get("priority") or ""
        lines.append(f"| {did} | {ttl} | {st} | {pr} | {_checkbox(st)} |")
    content = "\n".join(lines).rstrip() + "\n"

    # Write file into project tasks dir (task table path)
    tasks_dir = prj.get("tasks_dir_path")
    base = ws.get("workspace_path") if isinstance(ws.get("workspace_path"), str) else ""
    if not isinstance(tasks_dir, str) or not tasks_dir.strip():
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "VALIDATION_ERROR", "message": "Project tasks_dir_path is invalid."})
        return _err("VALIDATION_ERROR", "Project tasks_dir_path is invalid.")
    if not os.path.isabs(tasks_dir):
        tasks_dir_abs = os.path.normpath(os.path.join(base, tasks_dir))
    else:
        tasks_dir_abs = os.path.normpath(tasks_dir)
    try:
        os.makedirs(tasks_dir_abs, exist_ok=True)
    except OSError as e:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "CONFLICT", "message": "Unable to create tasks directory on disk.", "detail": str(e)})
        return _err("CONFLICT", "Unable to create tasks directory on disk.", detail=str(e))

    table_path = os.path.join(tasks_dir_abs, "TASKS.md")
    try:
        with open(table_path, "w", encoding="utf-8") as f:
            f.write(content)
    except OSError as e:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "CONFLICT", "message": "Failed to write task table file.", "detail": str(e)})
        return _err("CONFLICT", "Failed to write task table file.", detail=str(e))

    prj["last_task_table_generated_at"] = now
    prj["task_table_md_path"] = table_path
    prj["updated_at"] = now
    _save("projects.json", projects)

    act = _append_activity(ws.get("id"), prj.get("id"), None, "task_table_generated",
                           payload={"path": table_path, "rowCount": len(rows), "includeSubtasks": includeSubtasks, "includeDone": includeDone, "sortBy": sortBy})

    _audit(ws.get("id"), prj.get("id"), "ok", meta={"rows": len(rows)})
    return {"project": prj, "path": table_path, "content": content, "row_count": len(rows), "activity": act}

def listProjects(status=None, q=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "listProjects"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)

        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))

        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _log(workspace_id, project_id, task_id, event_type, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _new_id("acf_act"),
            "workspace_id": workspace_id or "unknown",
            "project_id": project_id,
            "task_id": task_id,
            "event_type": event_type,
            "message": None,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _pick_active_workspace(workspaces):
        candidates = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
        candidates.sort(key=lambda w: (w.get("updated_at") or "", w.get("created_at") or ""), reverse=True)
        return candidates[0] if candidates else None

    try:
        if status is not None and (not isinstance(status, str) or status not in ("active", "archived")):
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived", field="status")
        if q is not None and not isinstance(q, str):
            # Relax: allow other types by casting (audit sent q=42)
            q = str(q)
        if limit is not None and not isinstance(limit, int):
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "limit must be an integer when provided.", field="limit")
        if limit is None:
            limit = 50
        if limit < 1 or limit > 200:
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "limit": limit})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "cursor must be a string when provided.", field="cursor")

        workspaces = _load("workspaces.json")
        projects = _load("projects.json")

        ws = _pick_active_workspace(workspaces)
        if not ws:
            _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
            return _err("VALIDATION_ERROR", "No active workspace has been set.", failed_precondition=True)

        ws_id = ws.get("id")

        rows = [p for p in projects if isinstance(p, dict) and p.get("workspace_id") == ws_id]
        if status is not None:
            rows = [p for p in rows if p.get("status") == status]
        if q is not None and q.strip() != "":
            qq = q.strip().lower()
            rows = [p for p in rows if (p.get("name") or "").lower().find(qq) >= 0]

        rows.sort(key=lambda p: (p.get("updated_at") or "", p.get("created_at") or ""), reverse=True)

        # Cursor is base64 of last project's updated_at|id
        start_idx = 0
        if cursor:
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
                parts = raw.split("|", 1)
                if len(parts) == 2:
                    last_updated, last_id = parts
                    for i, p in enumerate(rows):
                        if (p.get("updated_at") or "") == last_updated and p.get("id") == last_id:
                            start_idx = i + 1
                            break
            except Exception:
                # Treat invalid cursor as validation error
                _log(ws_id, None, None, "context_viewed", payload={"endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000)})
                return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

        page = rows[start_idx:start_idx + limit]
        has_more = (start_idx + limit) < len(rows)
        next_cursor = None
        if has_more and page:
            last = page[-1]
            token = f"{last.get('updated_at') or ''}|{last.get('id') or ''}"
            next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("utf-8")

        _log(ws_id, None, None, "context_viewed", payload={"endpoint": endpoint, "status": "success", "latency_ms": int((time.time() - t0) * 1000), "returned": len(page), "total": len(rows)})
        return {"projects": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}
    except Exception as e:
        _log("unknown", None, None, "context_viewed", payload={"endpoint": endpoint, "status": "error", "latency_ms": int((time.time() - t0) * 1000), "exception": type(e).__name__})
        return _err("CONFLICT", "Unexpected server error.")

def getProject(projectId, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getProject"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, event_type, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": None,
            "event_type": event_type,
            "message": None,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, "context_viewed", payload=payload)

    if not isinstance(projectId, str) or not projectId.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "projectId must be a non-empty string.", "field": "projectId"})
        return _err("VALIDATION_ERROR", "projectId must be a non-empty string.", field="projectId")
    pid = projectId.strip()

    # Pattern per tool schema; BUT relax to allow callers passing wrong id (audit showed workspace id)
    if re.match(r"^acf_prj_[0-9A-HJKMNP-TV-Z]{10,}$", pid) is None:
        # try to interpret as workspace id => return its active project
        workspaces = _load("workspaces.json")
        projects = _load("projects.json")
        ws = next((w for w in workspaces if w.get("id") == pid), None)
        if ws and ws.get("active_project_id"):
            p = next((pp for pp in projects if pp.get("id") == ws.get("active_project_id")), None)
            if p:
                _append_activity(ws.get("id"), p.get("id"), "context_viewed", payload={"endpoint": endpoint, "resolvedFrom": "workspaceId"})
                _audit(ws.get("id"), p.get("id"), "ok", meta={"resolvedFrom": "workspaceId"})
                return {"project": p}
        # otherwise validation error
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "projectId is malformed.", "field": "projectId"})
        return _err("VALIDATION_ERROR", "projectId is malformed.", field="projectId")

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")

    # requires a workspace set: choose any active workspace as current context
    ws = next((w for w in workspaces if w.get("status") == "active"), None)
    if not ws:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No workspace has been set."})
        return _err("VALIDATION_ERROR", "No workspace has been set.")

    proj = next((p for p in projects if p.get("id") == pid and p.get("workspace_id") == ws.get("id")), None)
    if not proj:
        _audit(ws.get("id"), None, "error", error={"code": "NOT_FOUND", "message": "Project not found in the current workspace.", "projectId": pid})
        return _err("NOT_FOUND", "Project not found in the current workspace.", projectId=pid)

    _append_activity(ws.get("id"), proj.get("id"), "context_viewed", payload={"endpoint": endpoint})
    _audit(ws.get("id"), proj.get("id"), "ok")
    return {"project": proj}

