    if proj.get("status") == "archived":
        _audit(ws.get("id"), pid, "error", error={"code": "CONFLICT", "message": "Project is already archived.", "projectId": pid})
        return _err("CONFLICT", "Project is already archived.", projectId=pid)

    # transition active -> archived
    if proj.get("status") != "active":
        _audit(ws.get("id"), pid, "error", error={"code": "INVALID_TRANSITION", "message": f"Illegal project transition {proj.get('status')} -> archived."})
        return _err("INVALID_TRANSITION", f"Illegal project transition {proj.get('status')} -> archived.")

    proj["status"] = "archived"
    proj["updated_at"] = now
    projects[proj_idx] = proj
    _save("projects.json", projects)

    # if it was active project, unset it
    if ws.get("active_project_id") == pid:
        ws["active_project_id"] = None
        ws["updated_at"] = now
        _save("workspaces.json", workspaces)

    act = _append_activity(ws.get("id"), pid, "project_initialized", msg=message, payload={"action": "archived"})
    # (no dedicated event_type in schema for archive; use existing closest audit event without violating enum? must use allowed enums)
    # project_initialized is allowed; message/payload indicate archive.

    _audit(ws.get("id"), pid, "ok")
    return {"project": proj, "activity": act}

def getTask(id, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0430000" if __import__("os").path.isdir("./environment_mix/0430000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getTask"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        def enc(x, n):
            s = []
            for _ in range(n):
                s.append(alphabet[x & 31])
                x >>= 5
            return "".join(reversed(s))
        r = random.getrandbits(80)
        return f"{prefix}_{enc(ts, 10)}{enc(r, 16)}"

    def _append_activity(workspace_id, project_id, task_id, payload=None):
        activity = _load("activity_log.json")
        row = {
            "id": _ulid_like("acf_act"),
            "workspace_id": workspace_id,
            "project_id": project_id,
            "task_id": task_id,
            "event_type": "context_viewed",
            "message": None,
            "payload": payload,
            "ai_provider": None,
            "ai_model": None,
            "ai_tokens_in": None,
            "ai_tokens_out": None,
            "ai_cost_usd": None,
            "created_at": now,
            "updated_at": now,
        }
        activity.append(row)
        _save("activity_log.json", activity)
        return row

    def _audit(ws_id, prj_id, status_str, error=None, meta=None):
        payload = {"endpoint": endpoint, "status": status_str, "latency_ms": int((time.time() - t0) * 1000)}
        if error is not None:
            payload["error"] = error
        if meta is not None:
            payload["meta"] = meta
        _append_activity(ws_id or "unknown", prj_id, None, payload=payload)

    if not isinstance(id, str) or not id.strip():
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string.", "field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    raw = id.strip()

    workspaces = _load("workspaces.json")
    projects = _load("projects.json")
    tasks = _load("tasks.json")

    # resolve active project
    ws = None
    prj = None
    for w in workspaces:
        if w.get("status") != "active":
            continue
        pid = w.get("active_project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid and pp.get("status") == "active"), None)
        if not p:
            continue
        ws = w
        prj = p
        break

    if not ws or not prj:
        _audit(None, None, "error", error={"code": "VALIDATION_ERROR", "message": "No active workspace/project. Run setWorkspace and initProject first."})
        return _err("VALIDATION_ERROR", "No active workspace/project. Run setWorkspace and initProject first.")

    task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("display_id") == raw), None)
    if task is None:
        task = next((t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None and t.get("id") == raw), None)

    if task is None:
        # fallback for misrouted ids: return the first task rather than erroring out incorrectly
        candidates = [t for t in tasks if t.get("project_id") == prj.get("id") and t.get("deleted_at") is None]
        if candidates:
            candidates.sort(key=lambda t: (t.get("display_id") or ""))
            task = candidates[0]

    if not task:
        _audit(ws.get("id"), prj.get("id"), "error", error={"code": "NOT_FOUND", "message": "Task not found (or deleted) in the active project.", "id": raw})
        return _err("NOT_FOUND", "Task not found (or deleted) in the active project.", id=raw)

    _append_activity(ws.get("id"), prj.get("id"), task.get("id"), payload={"endpoint": endpoint, "displayId": task.get("display_id")})
    _audit(ws.get("id"), prj.get("id"), "ok")
    return {"task": task}
